export const TABLA_TECNICOS = new Table({
  name: process.env.TABLA_TECNICOS,
  documentClient: db,
  partitionKey: { name: 'TECNICO_ID', type: 'number' }
});

export const TABLA_ASIGNACIONES = new Table({
  name: process.env.TABLA_ASIGNACIONES,
  documentClient: db,
  partitionKey: { name: 'PLAZA_ID', type: 'number' },
  sortKey: { name: 'TECNICO_ID', type: 'number' },
  indexes: {
    PorTecnico: {
      type: 'global',
      partitionKey: { name: 'TECNICO_ID', type: 'number' },
      sortKey: { name: 'PLAZA_ID', type: 'number' }
    }
  }
});

export const MODELO_TECNICO = new Entity({
  name: 'Tecnico',
  table: TABLA_TECNICOS,
  entityAttribute: false,
  timestamps: false,
  schema: item({
    tecnicoId: number().key().savedAs('TECNICO_ID'),
    nombre: string().savedAs('NOMBRE'),
    apellidos: string().savedAs('APELLIDOS'),
    email: string().savedAs('EMAIL')
  })
});

export const MODELO_ASIGNACION = new Entity({
  name: 'Asignacion',
  table: TABLA_ASIGNACIONES,
  entityAttribute: false,
  timestamps: false,
  schema: item({
    plazaId: number().key().savedAs('PLAZA_ID'),
    tecnicoId: number().key().savedAs('TECNICO_ID'),
    rol: string().savedAs('ROL')
  })
});

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_TECNICO } from '../../models/tecnico-asignacion.model.mjs';

export async function crearTecnicoRepository(tecnico) {
  await MODELO_TECNICO.build(EntityRepository).put(
    tecnico,
    { condition: { attr: 'tecnicoId', exists: false } }
  );
}

export async function listarTecnicosRepository() {
  const { Items = [] } = await MODELO_TECNICO.build(EntityRepository).scan(
    { consistent: true }
  );
  return Items;
}

import { crearTecnicoRepository, listarTecnicosRepository } from './repository.mjs';

export async function crearTecnicoService(nombre, apellidos, email) {
  const tecnicoId = Date.now();
  const tecnico = { tecnicoId, nombre, apellidos, email };
  await crearTecnicoRepository(tecnico);
  return tecnico;
}

export function listarTecnicosService() {
  return listarTecnicosRepository();
}

import { crearTecnicoService, listarTecnicosService } from './service.mjs';

