import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PLAZA } from '../../models/urbanizacion-plaza.model.mjs';
import { MODELO_TECNICO, MODELO_ASIGNACION } from '../../models/tecnico-asignacion.model.mjs';

export async function buscarPlazaRepository(plazaId) {
  const { Item } = await MODELO_PLAZA.build(EntityRepository).get(
    { plazaId },
    { consistent: true }
  );
  return Item;
}

export async function buscarTecnicoRepository(tecnicoId) {
  const { Item } = await MODELO_TECNICO.build(EntityRepository).get(
    { tecnicoId },
    { consistent: true }
  );
  return Item;
}

export async function asignarTecnicoRepository(plazaId, tecnicoId, rol) {
  const asignacion = { plazaId, tecnicoId, rol };
  await MODELO_ASIGNACION.build(EntityRepository).put(
    asignacion,
    { condition: { attr: 'plazaId', exists: false } }
  );
  return asignacion;
}

import { buscarPlazaRepository, buscarTecnicoRepository, asignarTecnicoRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarTecnicoService(plazaId, tecnicoId, rol) {
  const plaza = await buscarPlazaRepository(plazaId);
  const tecnico = await buscarTecnicoRepository(tecnicoId);
  if (!plaza || !tecnico) {
    throw new ReferenciaInexistenteError('No existe la plaza o el tecnico');
  }
  return asignarTecnicoRepository(plazaId, tecnicoId, rol);
}

import { asignarTecnicoService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const plazaId = Number(event.pathParameters.plazaId);
  const { tecnicoId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarTecnicoService(plazaId, tecnicoId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El tecnico ya está asignado a esa plaza' }) };
    }
    throw error;
  }
}

